-- Fakt kartochkalarining ruscha matni — 19-partiya:
-- Zebo G'aniyeva, Halima Xudoyberdiyeva, Dilbar Abdurahmonova.

-- ===== Zebo G'aniyeva =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родилась Зебо Ганиева?', fact_ru = 'Я родилась в 1923 году. Моё детство пришлось на тяжёлое время: в годы репрессий 1937 года пострадала моя мать.' WHERE id = 557;
UPDATE fact_cards SET topic_ru = 'Моя любовь к танцу', question_ru = 'На какое отделение поступила Зебо Ганиева в Ташкенте?', fact_ru = 'В 1937 году я приехала в Ташкент и поступила на хореографическое отделение при Узбекской государственной филармонии — моей мечтой была сцена.' WHERE id = 558;
UPDATE fact_cards SET topic_ru = 'Актёрское дело в Москве', question_ru = 'Где училась Зебо Ганиева в 1940 году?', fact_ru = 'В 1940 году я поступила на актёрский факультет государственного института искусств в Москве.' WHERE id = 559;
UPDATE fact_cards SET topic_ru = 'Добровольцем на фронт', question_ru = 'Что сделала Зебо Ганиева, когда началась война?', fact_ru = 'Когда началась война, я одной из первых ушла на фронт в рядах добровольцев.' WHERE id = 560;
UPDATE fact_cards SET topic_ru = 'Меткий стрелок', question_ru = 'Какое имя заслужила Зебо Ганиева на фронте?', fact_ru = 'В полку, где я служила, я за короткий срок заслужила имя меткого стрелка-снайпера, расторопной связистки и остроумной разведчицы — в том, чтобы вовремя доставить сведения о позициях врага, я была всем примером.' WHERE id = 561;
UPDATE fact_cards SET topic_ru = 'Моё ранение', question_ru = 'Какое ранение получила Зебо Ганиева в бою?', fact_ru = 'В бою я была тяжело ранена и почти год лечилась, пока не поправилась.' WHERE id = 562;
UPDATE fact_cards SET topic_ru = 'Роль царевны в кино', question_ru = 'В каком фильме снялась Зебо Ганиева?', fact_ru = 'После войны я исполнила роль хорезмской царевны в художественном фильме известного узбекского режиссёра Наби Ганиева «Тахир и Зухра».' WHERE id = 563;
UPDATE fact_cards SET topic_ru = 'Мой путь в науку', question_ru = 'Чем занималась Зебо Ганиева после войны?', fact_ru = 'Позже я работала как учёный-историк и востоковед — с поля боя я вернулась на поле науки.' WHERE id = 564;
UPDATE fact_cards SET topic_ru = 'Живая легенда', question_ru = 'Как называли Зебо Ганиеву ещё при жизни?', fact_ru = 'Ещё при жизни меня называли «живой легендой»; и сегодня для молодёжи проводят посвящённые мне духовно-просветительские мероприятия и показы документального фильма.' WHERE id = 565;
UPDATE fact_cards SET topic_ru = 'На защите Москвы', question_ru = 'В обороне какого города участвовала Зебо Ганиева в годы войны?', fact_ru = 'В годы войны я служила в рядах 3-й Московской коммунистической стрелковой дивизии и участвовала в боях за оборону Москвы.' WHERE id = 1828;
UPDATE fact_cards SET topic_ru = 'Снайперские курсы', question_ru = 'Где Зебо Ганиева обучилась тайнам меткой стрельбы?', fact_ru = 'На фронте я окончила снайперские курсы и стала стрелком.' WHERE id = 1829;
UPDATE fact_cards SET topic_ru = 'Задания разведки', question_ru = 'Сколько раз Зебо Ганиева переходила в тыл врага как разведчица?', fact_ru = 'Как разведчица я шестнадцать раз переходила линию фронта в тыл врага и возвращалась с важными сведениями.' WHERE id = 1830;
UPDATE fact_cards SET topic_ru = 'Мои награды', question_ru = 'Каким орденом была награждена Зебо Ганиева за боевые заслуги?', fact_ru = 'За боевые заслуги я была награждена орденом Красного Знамени.' WHERE id = 1831;
UPDATE fact_cards SET topic_ru = 'На страницах печати', question_ru = 'Чем прославилось имя Зебо Ганиевой в годы войны?', fact_ru = 'В годы войны газеты писали о моей отваге, мой снимок печатали в прессе, и моё имя стало известно многим.' WHERE id = 1832;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'В каком городе Зебо Ганиева провела последние годы жизни?', fact_ru = 'Я прожила долгую жизнь: после войны жила в Москве и там же скончалась в 2010 году.' WHERE id = 1833;
UPDATE fact_cards SET topic_ru = 'Память', question_ru = 'Как вспоминают Зебо Ганиеву в сегодняшнем Узбекистане?', fact_ru = 'Сегодня в Узбекистане обо мне печатают статьи, а о моей отваге рассказывают молодёжи как о примере.' WHERE id = 1834;

-- ===== Halima Xudoyberdiyeva =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Халима Худайбердыева?', fact_ru = 'Я родилась 17 мая 1947 года в Баяутском районе Сырдарьинской области.' WHERE id = 576;
UPDATE fact_cards SET topic_ru = 'Мои первые стихи', question_ru = 'Когда были напечатаны первые стихи Халимы Худайбердыевой?', fact_ru = 'Мои первые стихи были напечатаны в школьные годы, в 1964 году, в янгиерской районной газете.' WHERE id = 577;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Какой университет окончила Халима Худайбердыева?', fact_ru = 'В 1972 году я окончила факультет журналистики Ташкентского государственного университета, а позже училась и в литературном институте в Москве.' WHERE id = 578;
UPDATE fact_cards SET topic_ru = 'Моя первая книга', question_ru = 'Как называется первая поэтическая книга Халимы Худайбердыевой?', fact_ru = 'Моя первая поэтическая книга «Первая любовь» вышла в 1968 году; затем были изданы сборники «Белые яблоки», «Горы моей опоры», «Дед-солнце», «Тёплый снег», «Священная женщина».' WHERE id = 579;
UPDATE fact_cards SET topic_ru = 'В журнале «Саодат»', question_ru = 'Какого журнала Халима Худайбердыева была главным редактором?', fact_ru = 'В журнале «Саодат» я работала литературным сотрудником и заведующей отделом, а в 1982–1994 годах была главным редактором этого журнала.' WHERE id = 580;
UPDATE fact_cards SET topic_ru = 'Во главе женского комитета', question_ru = 'Какой комитет возглавляла Халима Худайбердыева?', fact_ru = 'В 1990–1994 годах я была председателем Комитета женщин Узбекистана и защищала интересы женщин.' WHERE id = 581;
UPDATE fact_cards SET topic_ru = 'О Томирис', question_ru = 'Как называется книга Халимы Худайбердыевой, посвящённая отважным женщинам?', fact_ru = 'В 1996 году вышла моя книга «Сказанное Томирис», посвящённая отважным женщинам; мои стихи переведены на многие иностранные языки.' WHERE id = 582;
UPDATE fact_cards SET topic_ru = 'Народная поэтесса', question_ru = 'Когда Халима Худайбердыева получила звание народной поэтессы?', fact_ru = 'В 1990 году я получила Государственную премию имени Хамзы, а в 1992 году удостоилась звания «Народная поэтесса Узбекистана».' WHERE id = 583;
UPDATE fact_cards SET topic_ru = '«Эль-юрт хурмати»', question_ru = 'Каким орденом была награждена Халима Худайбердыева в 2017 году?', fact_ru = 'В 2017 году указом главы нашего государства я была награждена орденом «Эль-юрт хурмати».' WHERE id = 584;
UPDATE fact_cards SET topic_ru = 'Школа моего имени', question_ru = 'Где создана школа творчества имени Халимы Худайбердыевой?', fact_ru = 'По почину Президента в Сырдарьинской области создана школа творчества моего имени — там учатся будущие поэты и писатели.' WHERE id = 585;
UPDATE fact_cards SET topic_ru = 'Мои поэтические сборники', question_ru = 'Какие поэтические сборники Халимы Худайбердыевой известны?', fact_ru = 'Изданы такие мои поэтические сборники, как «Белые яблоки» и «Горы моей опоры».' WHERE id = 1616;
UPDATE fact_cards SET topic_ru = '«Священная женщина»', question_ru = 'Кому посвящена книга Халимы Худайбердыевой «Священная женщина»?', fact_ru = 'Моя поэтическая книга «Священная женщина» посвящена прекрасным достоинствам узбекской женщины.' WHERE id = 1617;
UPDATE fact_cards SET topic_ru = 'Тема моей поэзии', question_ru = 'Что главным образом воспевала Халима Худайбердыева в своих стихах?', fact_ru = 'В своих стихах я воспевала мечты и чаяния узбекской женщины, любовь и верность Родине.' WHERE id = 1618;
UPDATE fact_cards SET topic_ru = 'Огненные строки', question_ru = 'Каким определением называли Халиму Худайбердыеву?', fact_ru = 'За то, что стихи мои смелы и страстны, меня называли «владычицей огненных строк».' WHERE id = 1619;
UPDATE fact_cards SET topic_ru = 'Значение моего имени', question_ru = 'Что означает имя Халима Худайбердыевой?', fact_ru = 'Имя «Халима» взято из арабского и означает «мягкая нравом, ласковая».' WHERE id = 1620;
UPDATE fact_cards SET topic_ru = 'В Союзе писателей', question_ru = 'Членом какого творческого союза была Халима Худайбердыева?', fact_ru = 'Я была членом Союза писателей Узбекистана и деятельно участвовала в литературной жизни.' WHERE id = 1621;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умерла Халима Худайбердыева?', fact_ru = 'Я скончалась в 2018 году. А стихи мои и сегодня живут в народе.' WHERE id = 1622;

-- ===== Dilbar Abdurahmonova =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Дильбар Абдурахманова?', fact_ru = 'Я родилась 1 мая 1936 года в Москве. Мой отец Гулам Абдурахманов был одним из ведущих певцов оперного театра — музыка в нашей семье звучала всегда.' WHERE id = 586;
UPDATE fact_cards SET topic_ru = 'Уроки скрипки', question_ru = 'По какому музыкальному инструменту училась Дильбар Абдурахманова?', fact_ru = 'В 1948–1955 годах я училась по классу скрипки в музыкальной школе имени Глиэра в Ташкенте, а вместе с тем занималась и в математической школе.' WHERE id = 587;
UPDATE fact_cards SET topic_ru = 'Ученица Ашрафи', question_ru = 'В чьём классе Дильбар Абдурахманова училась дирижированию?', fact_ru = 'В Ташкентской консерватории я окончила класс скрипки в 1959 году, а в 1960 году — класс оперно-симфонического дирижирования у знаменитого композитора Мухтара Ашрафи.' WHERE id = 588;
UPDATE fact_cards SET topic_ru = 'Скрипачка в оркестре', question_ru = 'В оркестре какого театра играла Дильбар Абдурахманова в студенческие годы?', fact_ru = 'В студенческие годы, в 1957–1960 годах, я играла на скрипке в оркестре театра Навои; в 1957 году я участвовала во Всемирном фестивале молодёжи в Москве как студентка-дирижёр.' WHERE id = 589;
UPDATE fact_cards SET topic_ru = 'Первая женщина-дирижёр', question_ru = 'Кто была первой женщиной, вставшей за дирижёрский пульт в Узбекистане?', fact_ru = 'С 1960 года я начала дирижировать в театре Навои — я стала первой женщиной, вставшей за дирижёрский пульт в Узбекистане.' WHERE id = 590;
UPDATE fact_cards SET topic_ru = 'Главный дирижёр', question_ru = 'В какие годы Дильбар Абдурахманова была главным дирижёром театра Навои?', fact_ru = 'В 1974–1990 годах я работала главным дирижёром и художественным руководителем театра Навои.' WHERE id = 591;
UPDATE fact_cards SET topic_ru = '«Тановар» и премия', question_ru = 'За постановку какого балета Дильбар Абдурахманова получила премию?', fact_ru = 'В 1973 году за постановку балета А. Козловского «Тановар» я удостоилась Государственной премии имени Хамзы; в моём репертуаре было более 60 опер и балетов.' WHERE id = 592;
UPDATE fact_cards SET topic_ru = 'Мои звания', question_ru = 'Когда Дильбар Абдурахманова стала народной артисткой СССР?', fact_ru = 'В 1969 году я стала народной артисткой Узбекистана, в 1977 году — народной артисткой СССР; в годы независимости я была награждена орденами «Мехнат шухрати» (2001) и «За самоотверженную службу» (2012).' WHERE id = 593;
UPDATE fact_cards SET topic_ru = 'Моё наставничество', question_ru = 'Где Дильбар Абдурахманова преподавала в звании профессора?', fact_ru = 'В Государственной консерватории Узбекистана я была профессором и преподавала молодым исполнителям оперное искусство.' WHERE id = 594;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умерла Дильбар Абдурахманова?', fact_ru = 'Я скончалась 20 марта 2018 года в Ташкенте.' WHERE id = 595;
UPDATE fact_cards SET topic_ru = 'Моё детство в Ташкенте', question_ru = 'В каком городе прошло детство Дильбар Абдурахмановой?', fact_ru = 'Хотя я родилась в Москве, детство моё прошло в Ташкенте. Здесь я училась в музыкальной школе и полюбила искусство.' WHERE id = 1564;
UPDATE fact_cards SET topic_ru = 'Моя учёба в консерватории', question_ru = 'В каком высшем учебном заведении училась Дильбар Абдурахманова?', fact_ru = 'После музыкальной школы я училась в Ташкентской государственной консерватории — сперва по классу скрипки, затем по дирижированию.' WHERE id = 1565;
UPDATE fact_cards SET topic_ru = 'Мой театр', question_ru = 'В каком театре работала Дильбар Абдурахманова?', fact_ru = 'Вся моя творческая жизнь связана с театром оперы и балета имени Алишера Навои. Этот театр — главная оперная и балетная сцена Узбекистана.' WHERE id = 1566;
UPDATE fact_cards SET topic_ru = 'Полвека моей службы', question_ru = 'Сколько времени Дильбар Абдурахманова работала в театре Навои?', fact_ru = 'В театре Навои я проработала почти полвека — сперва в оркестре, потом за дирижёрским пультом. Театр был мне вторым домом.' WHERE id = 1567;
UPDATE fact_cards SET topic_ru = 'Спектакли, которыми я дирижировала', question_ru = 'Сколькими оперными и балетными спектаклями дирижировала Дильбар Абдурахманова?', fact_ru = 'Как дирижёр я провела более 60 оперных и балетных спектаклей.' WHERE id = 1568;
UPDATE fact_cards SET topic_ru = 'Мой репертуар', question_ru = 'Какие произведения были в репертуаре Дильбар Абдурахмановой?', fact_ru = 'В моём репертуаре была и мировая классика, и оперы и балеты узбекских композиторов. К каждому спектаклю я готовилась с особой любовью.' WHERE id = 1569;
UPDATE fact_cards SET topic_ru = 'Ремесло дирижёра', question_ru = 'Какую работу выполняет дирижёр — человек той профессии, которой владела Дильбар Абдурахманова?', fact_ru = 'Дирижёр — это музыкант, ведущий за собой оркестр: палочкой в руке он соединяет всех музыкантов в единое звучание. Это ремесло я любила всем сердцем.' WHERE id = 1570;
